#!/usr/bin/env bash
set -euo pipefail

if [[ -z "${BASH_VERSION:-}" ]]; then
  echo "Uruchom ten skrypt przez bash: bash ./install-ROG-Ally-Audio-0.1.11-auto-kde-tray.sh"
  exit 1
fi

# This script must run as the normal SteamOS user, never as root/sudo.
# systemctl --user and the EasyEffects Flatpak are per-user resources.
if [[ "$(id -u)" -eq 0 ]]; then
  echo "Nie uruchamiaj tego skryptu przez sudo/root."
  echo "Zaloguj się jako użytkownik SteamOS (deck) i uruchom go bez sudo."
  exit 1
fi

DECK_HOME="/home/deck"
DECK_USER="$(id -un)"
DECK_GROUP="$(id -gn)"
PLUGIN_DIR="$DECK_HOME/homebrew/plugins/ROGAllyAudio"
BACKUP="$DECK_HOME/.local/share/allyx-audio-final/decky-0.1.11-auto-kde-$(date +%Y%m%d-%H%M%S)"
TMP="$(mktemp -d)"
DECKY_WAS_STOPPED=0

cleanup() {
  rm -rf "$TMP"
  # Never leave Decky Loader stopped if this script aborts mid-way.
  if [[ "$DECKY_WAS_STOPPED" == 1 ]] && ! systemctl is-active --quiet plugin_loader; then
    echo
    echo "Przywracam Decky Loader po przerwanym skrypcie..."
    sudo systemctl start plugin_loader || true
  fi
}
trap cleanup EXIT

if [[ "$(realpath -m "$HOME")" != "$DECK_HOME" ]]; then
  echo "Ten instalator zakłada katalog domowy $DECK_HOME (standardowe konto deck w SteamOS)."
  echo "Wykryto HOME=$HOME. Uruchom go jako użytkownik deck."
  exit 1
fi

for cmd in flatpak python3 systemctl sha256sum; do
  command -v "$cmd" >/dev/null 2>&1 || {
    echo "Brak wymaganego polecenia: $cmd"
    exit 1
  }
done

if ! systemctl list-unit-files plugin_loader.service --no-legend 2>/dev/null | grep -q '^plugin_loader\.service'; then
  echo "Nie znaleziono usługi plugin_loader — najpierw zainstaluj Decky Loader."
  exit 1
fi

export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"

fail() {
  echo
  echo "================ BŁĄD ================"
  echo "$1"
  echo
  echo "--- Session manager ---"
  systemctl --user --no-pager -l status decky-rog-ally-audio-session.service 2>/dev/null || true
  echo "--- KDE EasyEffects ---"
  systemctl --user --no-pager -l status decky-rog-ally-audio-easyeffects-kde.service 2>/dev/null || true
  echo "--- Gaming EasyEffects ---"
  systemctl --user --no-pager -l status decky-rog-ally-audio-easyeffects.service 2>/dev/null || true
  echo "--- Controller ---"
  systemctl --user --no-pager -l status decky-rog-ally-audio-controller.service 2>/dev/null || true
  echo "--- session.json ---"
  cat "$DECK_HOME/.config/rog-ally-audio/session.json" 2>/dev/null || true
  echo
  echo "--- status.json ---"
  cat "$DECK_HOME/.config/rog-ally-audio/status.json" 2>/dev/null || true
  echo
  echo "--- EasyEffects settings ---"
  dconf dump /com/github/wwmm/easyeffects/ 2>/dev/null | grep -E 'show-tray|service|autostart|process-all|no-window' || true
  echo "--- Flatpak override ---"
  flatpak override --user --show com.github.wwmm.easyeffects 2>/dev/null || true
  echo "--- Tray watcher ---"
  busctl --user get-property org.kde.StatusNotifierWatcher /StatusNotifierWatcher org.kde.StatusNotifierWatcher RegisteredStatusNotifierItems 2>/dev/null || true
  exit 1
}

echo "ROG Ally Audio 0.1.11 - automatic KDE tray + Gaming Mode handoff"
mkdir -p "$BACKUP"

echo
echo "==> 1/9 Backup"
[[ -d "$PLUGIN_DIR" ]] && cp -a "$PLUGIN_DIR" "$BACKUP/plugin" || true
[[ -d "$DECK_HOME/.local/share/decky-rog-ally-audio" ]] && cp -a "$DECK_HOME/.local/share/decky-rog-ally-audio" "$BACKUP/runtime-data" || true
[[ -d "$DECK_HOME/.config/rog-ally-audio" ]] && cp -a "$DECK_HOME/.config/rog-ally-audio" "$BACKUP/config" || true
mkdir -p "$BACKUP/systemd"
cp -a "$DECK_HOME/.config/systemd/user/"*rog-ally-audio* "$BACKUP/systemd/" 2>/dev/null || true
echo "Backup: $BACKUP"

echo
echo "==> 2/9 Weryfikacja pluginu"
printf '%s' '' | base64 -d > "$TMP/plugin.zip"
echo "0c439493e9b87ff6097df8b586239bb9ac6c4c2f19f9ebffd389e1a85facfada  $TMP/plugin.zip" | sha256sum -c -
mkdir "$TMP/plugin"
python3 -c 'import sys, zipfile; zipfile.ZipFile(sys.argv[1]).extractall(sys.argv[2])' "$TMP/plugin.zip" "$TMP/plugin"
python3 -m py_compile "$TMP/plugin/main.py" "$TMP/plugin/runtime/controller.py" "$TMP/plugin/runtime/session_manager.py"
find "$TMP/plugin" -name __pycache__ -type d -prune -exec rm -rf {} +
bash -n "$TMP/plugin/runtime/easyeffects-kde.sh"

echo
echo "==> 3/9 Instalacja pluginu Decky"
echo "    Potrzebuję hasła sudo, aby zatrzymać i później uruchomić Decky Loader."
sudo -v
sudo systemctl stop plugin_loader
DECKY_WAS_STOPPED=1
[[ "$PLUGIN_DIR" == "$DECK_HOME/homebrew/plugins/"* ]] || fail "Nieprawidłowa ścieżka pluginu: $PLUGIN_DIR"
sudo rm -rf "$PLUGIN_DIR"
sudo mkdir -p "$PLUGIN_DIR"
sudo cp -a "$TMP/plugin/." "$PLUGIN_DIR/"
sudo chown -R "$DECK_USER:$DECK_GROUP" "$PLUGIN_DIR"

echo
echo "==> 4/9 Pełna migracja runtime przez plugin"
PYTHONPATH="$PLUGIN_DIR" python3 - <<'PYBOOT' || fail "Bootstrap runtime nie powiódł się (szczegóły powyżej)."
from pathlib import Path
from backend.rog_ally_audio.runtime_manager import RuntimeManager

try:
    m = RuntimeManager(Path('/home/deck/homebrew/plugins/ROGAllyAudio'), Path('/home/deck'))
    if not m.easyeffects_installed():
        print("EasyEffects nie jest zainstalowany — instaluję Flatpak z Flathub (może potrwać kilka minut)...")
        m.install_easyeffects()
    state = m.bootstrap(force=True)
except Exception as exc:
    print(f"BŁĄD: {type(exc).__name__}: {exc}")
    raise SystemExit(2)
print(state.to_dict())
PYBOOT

echo
echo "==> 5/9 Start Decky"
sudo systemctl start plugin_loader
systemctl is-active --quiet plugin_loader || fail "Decky nie wystartował"
DECKY_WAS_STOPPED=0

echo
echo "==> 6/9 Weryfikacja automatycznego wyboru Desktop/Gaming"
KDE=0
if pgrep -u "$(id -u)" -x plasmashell >/dev/null 2>&1; then KDE=1; fi
SESSION_READY=0
for _ in $(seq 1 240); do
  [[ -f "$DECK_HOME/.config/rog-ally-audio/session.json" ]] || { sleep 0.25; continue; }
  phase="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("phase",""))' "$DECK_HOME/.config/rog-ally-audio/session.json" 2>/dev/null || true)"
  mode="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("mode",""))' "$DECK_HOME/.config/rog-ally-audio/session.json" 2>/dev/null || true)"
  if [[ "$phase" == "ready" ]]; then
    if [[ "$KDE" == 1 && "$mode" == "kde" ]]; then SESSION_READY=1; break; fi
    if [[ "$KDE" == 0 && "$mode" == "gaming" ]]; then SESSION_READY=1; break; fi
  fi
  sleep 0.25
done
[[ "$SESSION_READY" == 1 ]] || fail "Session manager nie osiągnął stanu ready dla właściwego trybu w 60 s (oczekiwano: $([[ "$KDE" == 1 ]] && echo kde || echo gaming))."

systemctl --user is-active --quiet decky-rog-ally-audio-session.service || fail "Session manager jest nieaktywny"
systemctl --user is-active --quiet decky-rog-ally-audio-controller.service || fail "Kontroler jest nieaktywny"

if [[ "$KDE" == 1 ]]; then
  systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects-kde.service || fail "KDE EasyEffects nie działa"
  ! systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects.service || fail "Headless EasyEffects nie powinien działać równolegle w KDE"
  if command -v dconf >/dev/null 2>&1; then
    [[ "$(dconf read /com/github/wwmm/easyeffects/show-tray-icon 2>/dev/null || true)" == "true" ]] || fail "show-tray-icon nie jest włączone"
  else
    echo "  Uwaga: brak polecenia dconf — pomijam sprawdzenie show-tray-icon."
  fi
else
  systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects.service || fail "Gaming EasyEffects nie działa"
  ! systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects-kde.service || fail "KDE EasyEffects nie powinien działać w Gaming Mode"
fi

echo
echo "==> 7/9 Weryfikacja DSP/controller"
sleep 3
python3 - <<'PYSTATUS' || fail "Weryfikacja status.json nie powiodła się (szczegóły powyżej)."
import json
import sys

p = '/home/deck/.config/rog-ally-audio/status.json'
try:
    s = json.load(open(p))
except Exception as exc:
    print(f"BŁĄD: nie mogę odczytać {p}: {exc}")
    raise SystemExit(2)

problems = []
if s.get('controller_ok') is not True:
    problems.append('controller_ok != true')
if s.get('easyeffects_server_ok') is not True:
    problems.append('easyeffects_server_ok != true')
if s.get('easyeffects_service_active') is not True:
    problems.append('easyeffects_service_active != true')
streams = int(s.get('audio_streams') or 0)
expected = int(s.get('dsp_effects_expected') or 0)
dsp = s.get('dsp_status')
if streams > 0 and expected == 5 and dsp != 'chain-present':
    problems.append(f'oczekiwano chain-present, jest {dsp}')
if streams > 0 and expected == 0 and dsp != 'bypass-confirmed':
    problems.append(f'oczekiwano bypass-confirmed, jest {dsp}')
if problems:
    print('BŁĄD: ' + '; '.join(problems))
    print(json.dumps(s, indent=2, ensure_ascii=False))
    raise SystemExit(2)
print(json.dumps(s, indent=2, ensure_ascii=False))
PYSTATUS

echo
echo "==> 8/9 Weryfikacja tray KDE"
if [[ "$KDE" == 1 ]]; then
  override="$(flatpak override --user --show com.github.wwmm.easyeffects 2>/dev/null || true)"
  grep -q 'org.kde.StatusNotifierWatcher' <<<"$override" || fail "Brak automatycznego uprawnienia StatusNotifierWatcher"

  # Wait until EasyEffects registers a StatusNotifierItem. Verify by querying
  # Title/Id for every item in Plasma's watcher, not merely by counting icons.
  TRAY_OK=0
  for _ in $(seq 1 40); do
    if python3 - <<'PYTRAY'
import re, subprocess, sys
cmd=['busctl','--user','get-property','org.kde.StatusNotifierWatcher','/StatusNotifierWatcher','org.kde.StatusNotifierWatcher','RegisteredStatusNotifierItems']
r=subprocess.run(cmd,text=True,capture_output=True)
if r.returncode:
    raise SystemExit(1)
items=re.findall(r'"([^"]+)"',r.stdout)
for item in items:
    if '/' in item:
        service, path = item.split('/',1)
        path='/' + path
    else:
        service, path = item, '/StatusNotifierItem'
    for iface in ('org.kde.StatusNotifierItem','org.freedesktop.StatusNotifierItem'):
        for prop in ('Title','Id'):
            q=subprocess.run(['busctl','--user','get-property',service,path,iface,prop],text=True,capture_output=True)
            text=(q.stdout+' '+q.stderr).lower()
            if 'easy effects' in text or 'easyeffects' in text or 'com.github.wwmm.easyeffects' in text:
                print('EasyEffects tray:', item)
                raise SystemExit(0)
raise SystemExit(1)
PYTRAY
    then TRAY_OK=1; break; fi
    sleep 0.25
  done
  [[ "$TRAY_OK" == 1 ]] || fail "EasyEffects działa w KDE, ale nie zarejestrował ikony w StatusNotifierWatcher"
  echo "  EasyEffects tray: OK"
else
  echo "  Gaming Mode: tray celowo wyłączony"
fi

echo
echo "==> 9/9 Test przeżycia po starcie Decky"
sleep 8
systemctl --user is-active --quiet decky-rog-ally-audio-session.service || fail "Session manager zgasł po starcie Decky"
systemctl --user is-active --quiet decky-rog-ally-audio-controller.service || fail "Kontroler zgasł po starcie Decky"
if [[ "$KDE" == 1 ]]; then
  systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects-kde.service || fail "KDE EasyEffects zgasł po starcie Decky"
else
  systemctl --user is-active --quiet decky-rog-ally-audio-easyeffects.service || fail "Gaming EasyEffects zgasł po starcie Decky"
fi

echo
echo "========================================"
echo "GOTOWE — 0.1.11 działa bez ręcznych przejść."
if [[ "$KDE" == 1 ]]; then
  echo "KDE: EasyEffects działa jako normalna aplikacja Wayland + tray."
  echo "Nie musisz uruchamiać EasyEffects ręcznie."
else
  echo "Gaming Mode: działa trwały headless EasyEffects."
fi
echo "Przejście KDE <-> Gaming Mode jest od teraz automatyczne."
